<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); Illuminate\Support\Facades\Auth::loginUsingId(1); view()->share("errors", new Illuminate\Support\MessageBag()); $teams = App\Models\Team::with(["leader","members"])->get(); $teamIds = $teams->pluck("id"); $memberIds = $teams->flatMap(fn($t)=>$t->members->pluck("id"))->unique()->values(); $citationsByMember = App\Models\Citation::whereIn("issued_by",$memberIds)->where("issued_at",">=",now()->startOfMonth())->selectRaw("issued_by, COUNT(*) AS cnt")->groupBy("issued_by")->pluck("cnt","issued_by"); $citationByTeam = []; foreach ($teams as $team) { $count = 0; foreach ($team->members as $m) $count += (int)($citationsByMember[$m->id] ?? 0); $citationByTeam[$team->id] = $count; } $zoneCounts = App\Models\Zone::whereIn("team_id",$teamIds)->selectRaw("team_id, COUNT(*) AS cnt")->groupBy("team_id")->pluck("cnt","team_id"); $stats = ["total"=>App\Models\Team::count(),"active"=>App\Models\Team::where("is_active",true)->count(),"members"=>(int)Illuminate\Support\Facades\DB::table("team_user")->distinct()->count("user_id"),"citations_this_month"=>(int)$citationsByMember->sum()]; $html = view("teams.index",compact("teams","stats","zoneCounts","citationByTeam"))->with("hasFilters",false)->render(); file_put_contents(__DIR__."/teams_render.html",$html); echo "saved\n";
